// The six Unsloth Qwen3.8 Flash Next GGUF quantizations: embedding, prompt experts and Q2_K decode.
// Small quantized blocks are generated by the pinned ggml and compared with its CPU dequantizer.
#include "strata/kernels/dequant_bf16.hpp"
#include "strata/kernels/iq_kernels.hpp"
#include "strata/kernels/native_mmvq.hpp"

#include "ggml.h"

#include <cuda_runtime.h>

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <vector>

namespace {

constexpr int kTypes[] = {42, 10, 11, 12, 13, 14};
constexpr int kRows = 4, kCols = 512;

void ck(cudaError_t e, const char* what) {
    if (e != cudaSuccess) { std::fprintf(stderr, "%s: %s\n", what, cudaGetErrorString(e)); std::exit(2); }
}

bool close(float got, float want, float abs = 0.0001f, float rel = 0.0001f) {
    return std::isfinite(got) && std::fabs(got - want) <= abs + rel * std::fabs(want);
}

bool run(int type) {
    const auto* tr = ggml_get_type_traits((ggml_type) type);
    if (!tr || !tr->from_float_ref || !tr->to_float || !strata::kernels::iq_embed_supported(type) ||
        !strata::kernels::native_mmvq_supported(type)) return false;
    const size_t rb = strata::kernels::iq_row_bytes(type, kCols);
    if (!rb || rb != (size_t) kCols / ggml_blck_size((ggml_type) type) * ggml_type_size((ggml_type) type))
        return false;

    std::vector<uint8_t> host(rb * kRows);
    std::vector<float> want(kRows * kCols);
    for (int r = 0; r < kRows; ++r) {
        std::vector<float> source(kCols);
        for (int c = 0; c < kCols; ++c)
            source[c] = 0.21f * std::sin((float) (c * 13 + r * 31)) + 0.05f * std::cos((float) (c * 7 - r));
        tr->from_float_ref(source.data(), host.data() + r * rb, kCols);
        tr->to_float(host.data() + r * rb, want.data() + r * kCols, kCols);
    }

    uint8_t* dw = nullptr;
    int32_t* di = nullptr;
    float* dout = nullptr;
    uint16_t* d16 = nullptr;
    ck(cudaMalloc(&dw, host.size()), "weights allocation");
    ck(cudaMalloc(&di, 3 * sizeof(int32_t)), "tokens allocation");
    ck(cudaMalloc(&dout, 3 * kCols * sizeof(float)), "embedding allocation");
    ck(cudaMalloc(&d16, 2 * kRows * kCols * sizeof(uint16_t)), "expert allocation");
    ck(cudaMemcpy(dw, host.data(), host.size(), cudaMemcpyHostToDevice), "weights copy");
    const int32_t ids[] = {2, 0, 3};
    ck(cudaMemcpy(di, ids, sizeof(ids), cudaMemcpyHostToDevice), "tokens copy");

    strata::kernels::iq_embed_rows(type, dw, rb, di, 3, kCols, dout, nullptr);
    std::vector<float> actual(3 * kCols);
    ck(cudaMemcpy(actual.data(), dout, actual.size() * sizeof(float), cudaMemcpyDeviceToHost), "embedding copy");
    bool ok = true;
    for (int r = 0; r < 3; ++r)
        for (int c = 0; c < kCols; ++c)
            if (!close(actual[r * kCols + c], want[ids[r] * kCols + c])) ok = false;

    strata::kernels::iq_dequant_f32(type, dw + rb, kCols, dout, nullptr);
    ck(cudaMemcpy(actual.data(), dout, kCols * sizeof(float), cudaMemcpyDeviceToHost), "single row copy");
    for (int c = 0; c < kCols; ++c)
        if (!close(actual[c], want[kCols + c])) ok = false;

    strata::kernels::iq_dequant_gu_f16(type, dw, dw + 2 * rb, 2, kCols, d16, nullptr);
    std::vector<uint16_t> halfs(2 * kRows * kCols);
    ck(cudaMemcpy(halfs.data(), d16, halfs.size() * sizeof(uint16_t), cudaMemcpyDeviceToHost), "expert copy");
    for (int r = 0; r < 4; ++r) {
        const int src = r % 2 == 0 ? r / 2 : 2 + r / 2;
        for (int c = 0; c < kCols; ++c)
            if (!close(ggml_fp16_to_fp32(halfs[r * kCols + c]), want[src * kCols + c], 0.001f, 0.001f)) ok = false;
    }

    // The Q2_K native dense/head path is newly enabled. Check its Q8_1 product against the CPU values.
    if (type == 10) {
        std::vector<float> x(kCols);
        for (int c = 0; c < kCols; ++c) x[c] = 0.5f * std::sin((float) (c * 3 + 1));
        uint8_t* dx = nullptr;
        float* dy = nullptr;
        const size_t xb = (size_t) kCols / 32 * 36;
        ck(cudaMalloc(&dx, xb), "q8 allocation");
        ck(cudaMalloc(&dy, kRows * sizeof(float)), "mmvq allocation");
        float* dxf = nullptr;
        ck(cudaMalloc(&dxf, x.size() * sizeof(float)), "input allocation");
        ck(cudaMemcpy(dxf, x.data(), x.size() * sizeof(float), cudaMemcpyHostToDevice), "input copy");
        strata::kernels::quantize_q8_1_rows(dxf, 1, kCols, dx, nullptr);
        strata::kernels::native_mmvq(type, dw, dx, dy, kCols, kRows, 1, nullptr);
        std::vector<uint8_t> qx(xb);
        std::vector<float> y(kRows);
        ck(cudaMemcpy(qx.data(), dx, xb, cudaMemcpyDeviceToHost), "q8 copy");
        ck(cudaMemcpy(y.data(), dy, y.size() * sizeof(float), cudaMemcpyDeviceToHost), "mmvq copy");
        for (int r = 0; r < kRows; ++r) {
            double ref = 0;
            for (int c = 0; c < kCols; ++c) {
                const uint8_t* b = qx.data() + (size_t) (c / 32) * 36;
                const uint16_t h = (uint16_t) (b[0] | (b[1] << 8));
                ref += (double) want[r * kCols + c] * (double) ggml_fp16_to_fp32(h) * (int8_t) b[4 + c % 32];
            }
            if (!close(y[r], (float) ref, 0.003f, 0.001f)) ok = false;
        }
        cudaFree(dxf); cudaFree(dx); cudaFree(dy);
    }

    cudaFree(dw); cudaFree(di); cudaFree(dout); cudaFree(d16);
    std::printf("  ggml type %2d: %s\n", type, ok ? "OK" : "FAILED");
    return ok;
}

}  // namespace

int main() {
    int count = 0;
    if (cudaGetDeviceCount(&count) != cudaSuccess || count == 0) return 77;
    bool ok = true;
    for (int type : kTypes) ok = run(type) && ok;
    return ok ? 0 : 1;
}
